def get_filepaths(repo_path, ignore_git_staged=False, include_git_unstaged=False):
    """
    Returns a list of file paths in the given git repository.
    """
    filepaths = []
    repo = git.Repo(repo_path)
    for root, dirs, files in os.walk(repo_path):
        for file in files:
            file_path = os.path.join(root, file)
            if is_ignored(repo, file_path):
                continue
            if ignore_git_staged and is_staged(repo, file_path):
                continue
            if include_git_unstaged or not is_staged(repo, file_path):
                filepaths.append(file_path)
    return filepaths
